print(json.dumps({'path':str(target),'sha256':hashlib.sha256(target.read_bytes()).hexdigest(),'counts':{v:sum(x['verdict']==v for x in report['deterministic']) for v in sorted({x['verdict'] for x in report['deterministic']})},'risks':[x['name'] for x in report['deterministic'] if x['risk']]},indent=2))
